				"Shows recommendation cards below the answer for what you want from DSH: when you want a page or small tool you can keep, it proposes a new personalized page, built in the background after you click Create; when you ask how to do something in this app or say a capability is missing, it recommends the built-in plugin that provides it, turned on when you click Enable.": "DSH에서 하고 싶은 일에 맞는 추천 카드를 답변 아래에 보여 줍니다. 계속 쓸 페이지나 작은 도구가 필요할 때는 새 맞춤 페이지를 제안하고, 만들기를 누르면 백그라운드에서 만듭니다. 이 앱에서 어떤 일을 하는 방법을 묻거나 기능이 없다고 말하면 그 기능을 제공하는 기본 제공 플러그인을 추천하고, 켜기를 누르면 켜집니다.",
